                'warsaw' => 'Warsaw',
                'krakow' => 'Krakow',
                'gdansk' => 'Gdansk',
                'torun' => 'Torun',
                'lwow' => 'Lwow',
                'vilnius' => 'Vilnius',
                'polotsk' => 'Polotsk',
                'konigsberg' => 'Konigsberg',
                'grodno' => 'Grodno',
