                'germany' => 'Germany',
                'soviet' => 'Soviet Union',
                'czechoslovakia' => 'Czechoslovakia',
                'koenigsberg' => 'To the Soviet Union',
                'before' => 'Poland 1921 - 1939',
                'after' => 'Poland after 1945',
                'poles_west' => 'Poles moved west',
                'germans_west' => 'Germans expelled west',
                'warsaw' => 'Warsaw',
                'wroclaw' => 'Wroclaw',
                'szczecin' => 'Szczecin',
                'gdansk' => 'Gdansk',
                'olsztyn' => 'Olsztyn',
                'vilnius' => 'Vilnius',
                'grodno' => 'Grodno',
