                ['k' => 'The forest', 'v' => 'about 1,500 sq km, both countries'],
                ['k' => 'Strictly protected core', 'v' => 'about 60 sq km'],
                ['k' => 'Wild bison', 'v' => 'about 800 on the Polish side'],
                ['k' => 'From Warsaw', 'v' => '4 h by car'],
