                ['photo' => 'boyen', 'w' => 1280, 'h' => 853, 'caption' => 'Inside the Prussian fortress of Boyen, built in the 1840s', 'credit' => 'Photo: Pudelek, CC BY-SA 4.0'],
                ['photo' => 'lipka', 'w' => 1280, 'h' => 856, 'caption' => 'The pilgrimage church at Swieta Lipka, finished in the 1690s', 'credit' => 'Photo: Roman Eugeniusz, CC BY-SA 3.0'],
                ['photo' => 'wilczy', 'w' => 1280, 'h' => 853, 'caption' => 'A bunker at the Wolfs Lair, blown up in January 1945', 'credit' => 'Photo: Einsamer Schuetze, CC BY-SA 3.0'],
